CREATE FUNCTION public.validate_workplace_setup_profile() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE s jsonb; g jsonb; k jsonb; e text; BEGIN s=NEW.profile->'workplaceSetup'; IF s IS NULL OR (TG_OP='UPDATE' AND s IS NOT DISTINCT FROM OLD.profile->'workplaceSetup') THEN RETURN NEW; END IF; IF s->>'version'<>'2' OR jsonb_typeof(s->'goals') IS DISTINCT FROM 'array' OR jsonb_typeof(s->'employees') IS DISTINCT FROM 'array' OR jsonb_typeof(s->'completedSteps') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Invalid workplace setup'; END IF; FOR e IN SELECT jsonb_array_elements_text(s->'employees') LOOP IF e NOT IN ('sam','sonny','eva','nour','dana','adam','abdullah') THEN RAISE EXCEPTION 'Invalid setup employee'; END IF; END LOOP; FOR g IN SELECT * FROM jsonb_array_elements(s->'goals') LOOP IF COALESCE(length(g->>'id'),0)=0 OR (g->>'owner'<>'general' AND NOT (s->'employees') ? (g->>'owner')) OR COALESCE(length(trim(g->>'title')),0)=0 OR jsonb_typeof(g->'kpis') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Invalid workplace goal'; END IF; IF jsonb_array_length(g->'kpis')=0 THEN RAISE EXCEPTION 'KPI required'; END IF; FOR k IN SELECT * FROM jsonb_array_elements(g->'kpis') LOOP IF COALESCE(length(k->>'id'),0)=0 OR COALESCE(length(trim(k->>'measure')),0)=0 OR COALESCE(length(trim(k->>'unit')),0)=0 OR (k->'baseline' IS NOT NULL AND k->'baseline'<>'null'::jsonb) THEN RAISE EXCEPTION 'Invalid KPI or unverified baseline'; END IF; END LOOP; END LOOP; IF s->>'stage' IN ('ready','complete') AND NOT (s->'completedSteps' @> '["objectives","employees","tools"]'::jsonb) THEN RAISE EXCEPTION 'All setup steps required'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_workplace_setup_profile BEFORE INSERT OR UPDATE OF profile ON public.workspaces FOR EACH ROW EXECUTE FUNCTION public.validate_workplace_setup_profile();